import unittest

from solution import is_schema_supported


class SchemaSupportTests(unittest.TestCase):
    def test_numeric_comparison_not_lexicographic(self):
        self.assertTrue(is_schema_supported("2.10.0"))
        self.assertFalse(is_schema_supported("2.7.2"))
        self.assertTrue(is_schema_supported("10.0.0"))
        self.assertFalse(is_schema_supported("1.99.99"))

    def test_boundary_and_leading_zeroes(self):
        self.assertTrue(is_schema_supported("2.7.3"))
        self.assertTrue(is_schema_supported("02.007.0003"))
        self.assertFalse(is_schema_supported("002.0007.0002"))
        self.assertTrue(is_schema_supported("2.7.4"))

    def test_malformed_strings(self):
        for revision in ("", "2.7", "2.7.3.0", "2..3", "v2.7.3", "2.7.-3", "2.7.3 ", " 2.7.3", "2.a.3"):
            with self.subTest(revision=revision), self.assertRaises(ValueError):
                is_schema_supported(revision)

    def test_non_strings(self):
        for revision in (None, 273, 2.73, [2, 7, 3], True):
            with self.subTest(revision=revision), self.assertRaises(TypeError):
                is_schema_supported(revision)


if __name__ == "__main__":
    unittest.main()

